import React, { useEffect, useState } from "react";
import MenuItem from "@mui/material/MenuItem";
import FormControl from "@mui/material/FormControl";
import Select from "@mui/material/Select";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import http from "../../services/utility";
import { apisPath } from "../../utils/path";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";
import { useDispatch } from "react-redux";

export default function Coupons() {
  const dispatch = useDispatch();
  const [chooseCat, setChooseCat] = useState("Price-wise");
  const [chooseCatMenu, setChooseCatMenu] = useState([
    { value: "Price-wise", name: "Price wise" },
    { value: "Percentage-wise", name: "Percent wise" },
  ]);
  const [tableData, setTableData] = useState([]);
  const [formData, setFormData] = useState({
    coupon: "",
    discount: "",
    qty: "",
    category: "",
  });
  const [noOfUser, setNoOfUser] = useState(false);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.coupons)
      .then(async (res) => {
        setTableData(res?.data?.coupons);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const uploadData = async (e) => {
    let form = { ...formData, category: chooseCat };
    if (!noOfUser) {
      form["qty"] = 0;
    }
    setFormData((prev) => {
      return { ...prev, category: chooseCat };
    });
    await http
      .post(apisPath?.admin?.coupons, form)
      .then((res) => {
        // console.log(res);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const deleteData = async (index) => {
    await http
      .delete(`${apisPath?.admin?.coupons}/${index}`)
      .then(async (res) => {
        // console.log(res?.data?.message);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        getData();
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const handleInputChange = (e) => {
    const { name, value } = e?.target;

    setFormData((prev) => {
      return { ...prev, [name]: value };
    });
  };

  const handleChange = (event) => {
    setChooseCat(event?.target?.value);
  };

  return (
    <div className="coupons">
      <h3 className="coupons__heading page_heading">Coupons</h3>
      <div className="coupons__content">
        <div className="coupons__content__top_content">
          <div className="coupons__content__top_content__add_coupon">
            <label htmlFor="coupon">Add coupon</label>
            <input
              type="text"
              id="coupon"
              name="coupon"
              placeholder="Enter here"
              value={formData?.coupon}
              onChange={handleInputChange}
            />
          </div>
          <div className="coupons__content__top_content__discount">
            <label htmlFor="discount">Discount</label>
            <input
              type="text"
              id="discount"
              name="discount"
              placeholder="Enter here"
              value={formData?.discount}
              onChange={handleInputChange}
            />
          </div>

          <div className="coupons__content__top_content__small_container">
            <div className="coupons__content__top_content__small_container__no_of_user">
              <label htmlFor="qty">
                Number of uses per user
                <label className="coupons__content__top_content__small_container__no_of_user__switch">
                  <input
                    type="checkbox"
                    onChange={(e) => {
                      setNoOfUser(e?.target?.checked);
                    }}
                  />
                  <span className="slider round"></span>
                </label>
              </label>
              {!noOfUser ? (
                <input
                  type="text"
                  id="qty"
                  name="qty"
                  placeholder="Enter here"
                  value={formData?.qty}
                  onChange={handleInputChange}
                  disabled
                />
              ) : (
                <input
                  type="text"
                  id="qty"
                  name="qty"
                  placeholder="Enter here"
                  value={formData?.qty}
                  onChange={handleInputChange}
                />
              )}
            </div>
            <div className="coupons__content__top_content__small_container__choose_cat">
              <label htmlFor="choose_cat">Choose category</label>
              <FormControl fullWidth>
                <Select value={chooseCat} onChange={handleChange}>
                  {chooseCatMenu?.map((item, index) => {
                    return (
                      <MenuItem value={item?.value} key={index}>
                        {item?.name}
                      </MenuItem>
                    );
                  })}
                </Select>
              </FormControl>
            </div>
          </div>
          <button className="button-red" onClick={uploadData}>
            Add
          </button>
        </div>
        <div className="coupons__content__coupon_list">
          <h4 className="coupons__heading page_subheading">Coupon list</h4>
          <div className="coupons__content__coupon_list__content">
            <CouponListTable tableData={tableData} deleteData={deleteData} />
          </div>
        </div>
      </div>
    </div>
  );
}

const CouponListTable = ({ tableData, deleteData }) => {
  const [tableHeader, setTableHeader] = useState([
    { name: "Code" },
    { name: "Category" },
    { name: "Discount" },
    { name: "Edit" },
  ]);

  return (
    <table>
      <tr>
        {tableHeader?.map((header, index) => {
          return (
            <th key={index}>
              <span>
                {header?.name} <ArrowDropDownIcon />
              </span>
            </th>
          );
        })}
      </tr>
      {tableData?.map((data, index) => {
        return (
          <tr key={index}>
            <td>#{data?.coupon}</td>
            <td>{data?.category}</td>
            {data?.category == "Percentage-wise" ? (
              <td>{data?.discount}% off</td>
            ) : (
              <td>&#8377;{data?.discount} off</td>
            )}
            <td>
              <button
                className="button-red"
                onClick={() => deleteData(data?.id)}
              >
                Delete
              </button>
            </td>
          </tr>
        );
      })}
    </table>
  );
};
